<div class="d-flex align-items-center gap-3 mb-4"><x-account-avatar :user="$employee" :large="true" /><div><h2 class="h5 mb-1">{{ $employee->name }}</h2><span class="text-body-secondary small">Employee profile</span></div></div>
<div class="card mb-4"><div class="card-body"><label for="pds-section" class="form-label">PDS section</label><select id="pds-section" class="form-select">@foreach($sections as $key=>$definition)<option value="{{ $key }}">{{ ucwords(str_replace('-', ' ', $key)) }}</option>@endforeach<option value="position-history">Position history (read only)</option></select><div class="form-check mt-3"><input id="show-history" type="checkbox" class="form-check-input"><label class="form-check-label" for="show-history">Show previous snapshot versions</label></div></div></div>
<x-hris.table id="pds-table" :endpoint="'/profile/'.$employee->id.'/personal/data'" :columns="[['key'=>'data','label'=>'Section details'],['key'=>'updated_at','label'=>'Saved']]" :actions="Gate::allows('writePds', $employee) ? [['name'=>'details','label'=>'Details'],['name'=>'edit','label'=>'Edit'],['name'=>'download','label'=>'Attachment'],['name'=>'delete','label'=>'Remove','danger'=>true]] : [['name'=>'details','label'=>'Details'],['name'=>'download','label'=>'Attachment']]"/>
