@push('scripts')<script>
document.addEventListener('hris:ready',()=>{
 const definitions=@json($sections),employee=@json($employee->id),tableEl=document.querySelector('#pds-table'),table=tableEl.table,select=document.querySelector('#pds-section'),form=document.querySelector('#pds-form'),history=document.querySelector('#show-history');
 const label=key=>key.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
 function childRow(value={}){const wrap=document.createElement('div');wrap.className='row g-2 mb-2';const index=crypto.randomUUID();for(const [key,type,text] of [['name','text','Child name'],['birthday','date','Birth date']]){const col=document.createElement('div');col.className='col-5';const lab=document.createElement('label');lab.className='form-label small';lab.htmlFor=`child-${index}-${key}`;lab.textContent=text;const input=document.createElement('input');input.id=lab.htmlFor;input.type=type;input.className='form-control';input.dataset.childField=key;input.defaultValue=value[key]||'';col.append(lab,input);wrap.append(col)}const col=document.createElement('div');col.className='col-2 align-self-end';const remove=document.createElement('button');remove.type='button';remove.className='btn btn-outline-danger';remove.textContent='×';remove.setAttribute('aria-label','Remove child');remove.onclick=()=>wrap.remove();col.append(remove);wrap.append(col);return wrap}
 function edit(row=null){const section=select.value,definition=definitions[section];if(!definition)return;const fields=document.querySelector('#pds-fields');fields.replaceChildren();
  Object.entries(definition.fields).filter(([key])=>!key.includes('.')).forEach(([key,rules])=>{
   const col=document.createElement('div');col.className='col-md-6';
   if(key==='original_date_to')return;
   if(key==='children'){col.className='col-12';const title=document.createElement('h3');title.className='h6 mt-3';title.textContent='Children';const list=document.createElement('div');list.id='children-list';(row?.data?.children||[]).forEach(child=>list.append(childRow(child)));const add=document.createElement('button');add.type='button';add.className='btn btn-sm btn-outline-secondary';add.textContent='Add child';add.onclick=()=>{if(list.children.length<30)list.append(childRow())};col.append(title,list,add);fields.append(col);return}
   const id=`pds-${key}`,lab=document.createElement('label');lab.className='form-label';lab.htmlFor=id;lab.textContent=/^\d/.test(key)?`Question ${key.replace('_','(')}${key.includes('_')?')':''}`:label(key);
   let input;const choice=rules.match(/(?:^|\|)in:([^|]+)/);
   if(choice||rules.includes('boolean')){input=document.createElement('select');input.className='form-select';const choices=choice?choice[1].split(','):['true','false'];if(!rules.startsWith('required'))input.append(new Option('Choose…',''));choices.forEach(value=>input.append(new Option(value==='true'?'Yes':value==='false'?'No':value,value)));}
   else{input=document.createElement(rules.includes('max:2000')||rules.includes('max:1000')?'textarea':'input');input.className='form-control';if(input.tagName==='INPUT'){input.type=rules.includes('date_format:Y-m-d')?'date':rules.includes('numeric')||rules.includes('integer')?'number':'text';if(input.type==='number'){input.min='0';input.step=rules.includes('numeric')?'0.01':'1'}}}
   input.id=id;input.name=`data.${key}`;input.required=rules.startsWith('required|');const max=rules.match(/max:(\d+)/);if(max&&input.type!=='number')input.maxLength=Number(max[1]);col.append(lab,input);fields.append(col);
  });
  HRIS.fillForm(form,row||{});if(section==='experience'){form.elements.namedItem('data.is_ongoing').value=String(row?.data?.is_ongoing??false);form.elements.namedItem('data.govt_service').value=row?.data?.govt_service==null?'':String(row.data.govt_service)}
  const attachment=['learning','government-id'].includes(section);document.querySelector('#pds-attachment').classList.toggle('d-none',!attachment);document.querySelector('#pds-file-status').textContent=row?.file_id?'Existing attachment retained.':'';document.querySelector('#pds-file').value='';form.dataset.endpoint=`/profile/${employee}/${section}${row?.id?'/'+row.id:''}`;form.dataset.method=row?.id?'PUT':'POST';HRIS.openModal('pds-modal');
 }
 function load(){const section=select.value,isHistory=section==='position-history';tableEl.dataset.endpoint=isHistory?`/hr/staff/${employee}/history`:`/profile/${employee}/${section}/data`;table.params.set('history',history.checked?'1':'0');table.columns=isHistory?[{key:'effective_date',label:'Effective date'},{key:'position_title',label:'Position'}]:[{key:'data',label:'Section details'},{key:'updated_at',label:'Saved'}];const head=tableEl.querySelector('thead tr');head.replaceChildren();[...table.columns,{label:'Actions'}].forEach(column=>{const th=document.createElement('th');th.scope='col';th.textContent=column.label;head.append(th)});table.page=1;history.disabled=isHistory||!definitions[section]?.snapshot;table.load()}
 select.addEventListener('change',load);history.addEventListener('change',load);document.querySelector('#create-pds')?.addEventListener('click',()=>edit(definitions[select.value]?.snapshot?[...table.rows.values()].find(row=>row.section===select.value):null));
 tableEl.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='details')HRIS.showDetails('PDS record',row.data||row);if(action==='edit')edit(row);if(action==='download'){if(row.file_id)window.open(`/files/${row.file_id}`,'_blank','noopener');else HRIS.feedback('This record has no attachment.',true)}if(action==='delete'&&!definitions[select.value]?.snapshot&&select.value!=='position-history'&&await HRIS.confirm('Remove this PDS entry?')){HRIS.feedback((await HRIS.request(`/profile/${employee}/${select.value}/${row.id}`,{method:'DELETE'})).message);table.load()}}catch(error){HRIS.feedback(error.message,true)}});
 HRIS.bindForm(form,{prepare:body=>{if(select.value==='family')body.data.children=[...document.querySelectorAll('#children-list > div')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-child-field]')].map(input=>[input.dataset.childField,input.value||null])));if(select.value==='experience'&&body.data.is_ongoing)body.data.date_to=null},success:()=>table.load()});
 document.querySelector('#upload-pds-file').addEventListener('click',async event=>{const button=event.currentTarget,file=document.querySelector('#pds-file').files[0];if(!file)return;button.disabled=true;try{const body=new FormData();body.set('purpose',select.value==='learning'?'certificate':'government-id');body.set('file',file);const result=await HRIS.request(`/employees/${employee}/files`,{method:'POST',body});form.elements.namedItem('file_id').value=result.id;form.elements.namedItem('remove_file').checked=false;HRIS.feedback('Attachment uploaded. Save the section to attach it.');document.querySelector('#pds-file-status').textContent=`${result.original_name} uploaded. Save the section to attach it.`}catch(error){HRIS.feedback(error.message,true)}finally{button.disabled=false}});
});
</script>@endpush
